<div class="grid gap-5 md:grid-cols-2"><x-ui.select name="assessment_id" label="Évaluation" :value="$item->assessment_id" :options="$assessments->mapWithKeys(fn($x)=>[$x->id=>$x->organization_name.' · '.$x->framework])" required/><x-ui.input name="title" label="Titre de la preuve" :value="$item->title" required/><x-ui.select name="type" label="Type" :value="$item->type" :options="['certificate'=>'Certificat','report'=>'Rapport','invoice'=>'Facture','photo'=>'Photo','policy'=>'Politique','other'=>'Autre']" required/><x-ui.select name="status" label="Statut" :value="$item->status ?: 'pending'" :options="['pending'=>'En attente','verified'=>'Vérifiée','rejected'=>'Refusée','expired'=>'Expirée']" required/><x-ui.input name="document_path" label="Chemin du document" :value="$item->document_path"/><x-ui.input name="expires_at" label="Date d’expiration" type="date" :value="optional($item->expires_at)->format('Y-m-d')"/><div class="md:col-span-2"><x-ui.textarea name="notes" label="Notes de vérification" :value="$item->notes"/></div></div>
